-- See https://wiki.hyprland.org/Configuring/Monitors/
-- TODO: manual review — unexpected token after 'require("/usr/share/hypr/stubs/hl.meta.lua")'
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.monitor({
	output = "HDMI-A-1",
	mode = "1280x720@50",
	position = "0x0",
	scale = "1",
})

-- Set programs that you use
local terminal = "wezterm"
local filemanager = "thunar"
local menu = "wofi --show drun"
local browser = "zen-browser"

-- Some default env vars.
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
-- env = WLR_DRM_NO_ATOMIC,1 # some nvidia fix
hl.env("MOZ_ENABLE_WAYLAND", "1")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
hl.env("GTK_USE_PORTAL", "1")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_MENU_PREFIX", "arch-")
hl.env("QT_QPA_PLATFORM", "wayland")
hl.env("SLD_VIDEODRIVER", "wayland")
hl.env("XCURSOR_THEME", "catppuccin-mocha-blue")
hl.env("GTK_THEME", "Catppuccin-Dark")
hl.env("PULSE_LATENCY_MSEC", "50")

hl.on("hyprland.start", function()
	hl.exec_cmd("swaync")
	hl.exec_cmd("hyprpm reload -n")
	hl.exec_cmd("/usr/lib/hyprpolkitagent")
	hl.exec_cmd("pactl set-default-sink alsa_output.pci-0000_01_00.1.hdmi-stereo")
	hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("awww-daemon")
	hl.exec_cmd("hyprctl setcursor catppuccin-mocha-blue 24")
	hl.exec_cmd("waybar")
	hl.exec_cmd("swayosd-server")
	hl.exec_cmd("~/.config/hypr/scripts/awww.sh")
	hl.exec_cmd("wpctl set-default alsa_output.pci-0000_01_00.1.hdmi-stereo")
	hl.exec_cmd('gsettings set org.gnome.desktop.interface gtk-theme "catppuccin-mocha-teal-standard+default"')
end)

