local mainMod = "SUPER"
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(filemanager))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + G", function()
	hl.plugin.hyprexpo.expo("toggle")
end)
hl.bind(mainMod .. " + C", hl.dsp.window.close())
hl.bind(mainMod .. " + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + S", hl.dsp.exec_cmd("flameshot gui"))
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("wlogout"))
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("vesktop"))
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd("hyprlock"))
hl.bind(mainMod .. " + z", hl.dsp.exec_cmd("sh -c 'hyprctl dispatch hy3:makegroup h'"))
hl.bind(mainMod .. " + x", hl.dsp.exec_cmd("sh -c 'hyprctl dispatch hy3:makegroup v'"))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.exec_cmd("hyprctl switchxkblayout current next"))
hl.bind(mainMod .. " + BracketRight", hl.dsp.exec_cmd("swayosd-client --output-volume raise"))
hl.bind(mainMod .. " + BracketLeft", hl.dsp.exec_cmd("swayosd-client --output-volume lower"))
hl.bind(mainMod .. " + BACKSPACE", hl.dsp.exec_cmd("swayosd-client --output-volume mute-toggle"))
-- hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd("sh -c \"killall waybar 2>/dev/null; waybar &\""))

